    query: Option<&crate::extensions::control_rig_query::RigQueryContext>,
    capture: bool,
) -> Result<(), String> {
    state.executed_steps = 0;
    state.to_world = to_world;
    state.calls.clear();
    state.traces.clear();
    let rebuild = state.runtime.as_ref().is_none_or(|runtime| runtime.definition != *definition);
    if rebuild {
        state.runtime = Some(ControlRigRuntime {
            definition: definition.clone(),
            hierarchy: RigHierarchy::new(
                definition.bones.clone(),
                definition.translation_tolerance,
            )?,
            values: definition.program.initial_values.clone(),
            curves: definition
                .curves
                .iter()
                .filter_map(|(key, value)| value.map(|value| (key.clone().into(), value)))
                .collect(),
        });
    }
    let runtime = state.runtime.as_mut().unwrap();
    for (binding, value) in inputs {
        binding.write(
            &mut runtime.values,
            definition.program.literal_count,
            value.clone(),
        )?;
    }
    let calls = &mut state.calls;
    let traces = &mut state.traces;
    let mut execute = |runtime: &mut ControlRigRuntime, entry: &str| {
        let capture = capture && entry == "Forwards Solve";
        let instruction = std::cell::Cell::new(0);
        let mut trace = |start, end, channel: &str, complex| {
            let hit = query
                .ok_or_else(|| "rig line trace is unavailable".to_owned())?
                .trace(start, end, channel, complex)?;
            if capture {
                traces.push(RigTraceSample { instruction: instruction.get(), start, end, hit });
            }
            Ok(hit)
        };
        let mut context = RigUnitContext {
            hierarchy: &mut runtime.hierarchy,
            curves: &runtime.curves,
            game_world,
            construction: false,
            delta_seconds,
            geometry: &definition.geometry,
            to_world,
            line_trace: query
                .map(|_| &mut trace as &mut crate::extensions::control_rig_units::RigLineTrace<'_>),
        };
        definition
            .program
            .execute(entry, &mut runtime.values, |pc, name, args| {
                let bones_before = if capture {
                    instruction.set(pc);
                    let indices = args.iter().filter_map(|value| context.hierarchy.item_index(value).ok().flatten()).collect::<Vec<_>>();
                    if indices.is_empty() {
                        Vec::new()
                    } else {
                        let mut snapshot = context.hierarchy.clone();
                        indices.into_iter().filter_map(|index| Some((index, snapshot.transform(index, RigSpace::Global, false).ok()?))).collect()
                    }
                } else {
                    Vec::new()
                };
                let result = context.call(name, args);
                if capture {
                    calls.push(RigCallSample { instruction: pc, arguments: args.to_vec(), bones_before });
                }
                result
            })
            .map_err(|error| {
                format!(
                    "{error}; operation {:?}",
                    definition.program.instructions.get(error.instruction)
                )
            })
    };
    if rebuild {
        execute(runtime, "Construction")?;
        state.initialization_count += 1;
    }

pub fn evaluate_players<F: QueryFilter>(
    time: Res<Time>,
    mut players: Query<(Entity, &mut AnimationGraphPlayer, &mut crate::extensions::SourceAnimationInputs, Option<&mut AnimationPoseUpdateGate>), (F, Without<ManualAnimationPlayer>)>,
    resources: SystemResources,
) {
    players.par_iter_mut().for_each(|(entity, mut player, inputs, mut gate)| {
        if gate.as_ref().is_some_and(|gate| !gate.update_graph) { return; }
        let playing = !player.is_paused();
        let initialize = gate.is_some() && player.get_context_arena().is_none_or(|arena| arena.frame_index() == 0);
        player.set_global_input_data("animation.evaluate_pose", initialize || gate.as_ref().is_none_or(|gate| gate.refresh_bones));
        if initialize {
            let delta = player.get_global_input_data("animation.delta_seconds").cloned();
            if delta.is_some() { player.set_global_input_data("animation.delta_seconds", 0.0_f32); }
            inputs.evaluate(entity, || run_animation_player(entity, player.reborrow(), &Time::default(), &resources));
            if let Some(delta) = delta { player.set_global_input_data("animation.delta_seconds", delta); }
        } else {
            let delta = player.get_global_input_data("animation.delta_seconds")
                .and_then(|value| value.as_f32().ok()).map_or(time.delta_secs(), |value| value);
            let mut animation_time = Time::default();
            animation_time.advance_by(std::time::Duration::from_secs_f32(delta.max(0.0)));
            inputs.evaluate(entity, || run_animation_player(entity, player.reborrow(), &animation_time, &resources));
        }
        if playing && player.get_error().is_none() && player.get_default_output_pose().is_some()
            && let Some(gate) = gate.as_mut() { gate.pending_update = false; }
    });
